  "flashcards": [
    {
      "id": "fc-23",
      "chapterId": "chapter-7",
      "category": "Axial vs Appendicular",
      "front": "Which bones make up the pectoral girdle?",
      "back": "The paired clavicles and scapulae.",
      "note": "The pectoral girdle belongs to the appendicular skeleton, not the axial."
    },
    {
      "id": "fc-24",
      "chapterId": "chapter-7",
      "category": "Axial Skeleton",
      "front": "What differentiates a true rib from a false rib?",
      "back": "True ribs attach directly to the sternum via their own costal cartilage.",
      "note": "False ribs lack independent, direct sternal attachments; floating ribs have no anterior attachment at all."
    },
    {
      "id": "fc-25",
      "chapterId": "chapter-7",
      "category": "Vertebral Column",
      "front": "How many vertebrae make up the cervical, thoracic, and lumbar regions?",
      "back": "7 cervical, 12 thoracic, 5 lumbar.",
      "note": "Remember meal times: breakfast at 7, lunch at 12, dinner at 5."
    },
    {
      "id": "fc-26",
      "chapterId": "chapter-7",
      "category": "Appendicular Skeleton",
      "front": "What three bones fuse to form a single coxal (hip) bone?",
      "back": "The ilium, ischium, and pubis.",
      "note": "They all meet at the acetabulum (the hip socket)."
    },
    {
      "id": "fc-27",
      "chapterId": "chapter-7",
      "category": "Axial Skeleton",
      "front": "Which standalone bone does not directly articulate with any other bone?",
      "back": "The hyoid bone.",
      "note": "It is anchored by muscles and acts as a base for tongue and laryngeal movement."
    },
    {
      "id": "fc-28",
      "chapterId": "chapter-7",
      "category": "Appendicular Skeleton",
      "front": "Which is the larger, medial, weight-bearing bone of the lower leg: tibia or fibula?",
      "back": "The tibia.",
      "note": "The fibula sits laterally and helps stabilize the ankle but does not bear weight."
    }
  ],
